arguments.new_string:
_ZERO_DIGITS = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE_DIGITS = {"BHD", "JOD", "KWD", "OMR", "TND"}

# Link names the docs list, with the canonical zone id to send instead.
_LINKS = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}

_SUPPORTED_LOCALES = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}

# locale -> (decimal separator, group separator, currency code position)
_NUMBER_STYLE = {
    "en-US": (".", ",", "before"),
    "en-GB": (".", ",", "before"),
    "ja-JP": (".", ",", "before"),
    "en-IN": (".", ",", "before"),
    "de-DE": (",", ".", "after"),
    "es": (",", ".", "after"),
    "de-CH": (".", "\u2019", "after"),
    "fr-FR": (",", "\u202f", "after"),
    "pt-BR": (",", ".", "before"),
}


def _tzdata_links() -> dict[str, str]:
    """Link name -> target from the system tz database, when it is installed."""
    links: dict[str, str] = {}
    paths = ["/usr/share/zoneinfo/tzdata.zi", "/usr/share/lib/zoneinfo/tzdata.zi"]
    try:
        import tzdata  # type: ignore

        paths.append(os.path.join(os.path.dirname(tzdata.__file__), "zoneinfo", "tzdata.zi"))
    except ImportError:
        pass
    for p in paths:
        try:
            with open(p, encoding="utf-8") as f:
                for row in f:
                    parts = row.split()
                    if len(parts) >= 3 and parts[0] == "L":
                        links[parts[2]] = parts[1]
            break
        except OSError:
            continue
    return links


def _canonical_zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\s*([+-])(\d{1,2})(?::?(\d{2}))?", tz)
    if m and (m.group(1) or m.group(2)) and not (tz.upper() in ("UTC", "GMT")):
        sign, hours, minutes = m.group(1), int(m.group(2)), int(m.group(3) or 0)
        if minutes:
            raise ValueError(f"offset {tz!r} is not a whole number of hours; Meridale has no zone for it")
        if hours == 0:
            return "Etc/UTC"
        # POSIX convention: the sign is inverted.
        return f"Etc/GMT{'-' if sign == '+' else '+'}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    if "/" in tz and not tz.startswith(("Etc/GMT", "Etc/UTC")):
        links = _tzdata_links()
        seen = 0
        while tz in links and seen < 5:
            tz = links[tz]
            seen += 1
    return tz


def _meridale_locale(posix: str) -> str:
    name = re.split(r"[.@]", posix.strip(), maxsplit=1)[0]
    parts = [p for p in re.split(r"[-_]", name) if p]
    if not parts or not parts[0].isalpha():
        return "en-US"
    lang = parts[0].lower()
    region = next((p.upper() for p in parts[1:] if len(p) == 2 and p.isalpha()), None)
    if region and f"{lang}-{region}" in _SUPPORTED_LOCALES:
        return f"{lang}-{region}"
    if lang in _SUPPORTED_LOCALES:
        return lang
    return "en-US"


def _digits(currency: str) -> int:
    code = currency.upper()
    return 0 if code in _ZERO_DIGITS else 3 if code in _THREE_DIGITS else 2


def _round(value: str, digits: int) -> Decimal:
    with localcontext() as ctx:
        ctx.prec = 60
        out = Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)
    return out + 0 if out == 0 else out  # zero has no sign


def _group(integer: str, indian: bool) -> list[str]:
    if indian and len(integer) > 3:
        head, tail = integer[:-3], integer[-3:]
        groups = []
        while len(head) > 2:
            groups.insert(0, head[-2:])
            head = head[:-2]
        if head:
            groups.insert(0, head)
        return groups + [tail]
    groups = []
    while len(integer) > 3:
        groups.insert(0, integer[-3:])
        integer = integer[:-3]
    return [integer] + groups


def _text(value: Decimal, currency: str, locale: str) -> str:
    decimal_sep, group_sep, position = _NUMBER_STYLE[locale]
    digits = _digits(currency)
    plain = f"{abs(value):.{digits}f}"
    integer, _, frac = plain.partition(".")
    number = group_sep.join(_group(integer, locale == "en-IN"))
    if digits:
        number += decimal_sep + frac
    if value < 0:
        number = "-" + number
    code = currency.upper()
    return f"{code}\u00a0{number}" if position == "before" else f"{number}\u00a0{code}"
